'use strict';
let state,tab='home',search='',month='',syncing=false,installPrompt,pad;
const main=document.getElementById('main'),dialog=document.getElementById('dialog'),body=document.getElementById('dialog-body');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const websiteURL='https://gestionpro-web-reservations-production.up.railway.app/';
const money=n=>new Intl.NumberFormat('fr-MA',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0)+' DH';
const clone=v=>JSON.parse(JSON.stringify(v));
const blank=()=>({clients:[],vehicles:[],contracts:[],reservations:[],maintenance:[],expenses:[],checks:[],finance:[],settings:{},pc_at:null,operations:[]});
const button=(text,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
function toast(text){let e=document.getElementById('toast');e.textContent=text;e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,6500)}
function route(t){tab=t;search='';render();window.scrollTo(0,0)}
function show(title,html){document.getElementById('dialog-title').textContent=title;body.innerHTML=html;if(!dialog.open)dialog.showModal()}
function input(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function select(name,label,options,value=''){return `<label>${label}<select name="${name}">${options.map(([k,t])=>`<option value="${esc(k)}" ${String(k)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function data(){return state.data}
function client(code){return data().clients.find(r=>r.code===code)}
function vehicle(code){return data().vehicles.find(r=>r.code===code)||(data().contract_vehicles||[]).find(r=>r.code===code)}
function operations(){return [...(data().operations||[]),...state.queue]}
function opFor(id){return operations().filter(o=>(o.record.code||o.record.numero||o.record.reference)===id).at(-1)}
function badge(id){const op=opFor(id);if(!op)return '<span class="badge">Données du PC</span>';if(op.status==='applied')return '<span class="badge">✓ Enregistré sur le PC</span>';if(op.status==='rejected')return `<span class="badge danger">À corriger</span><p class="note">${esc(op.message)}</p>`;if(!op.status)return '<span class="badge warn">Sur le téléphone · à envoyer</span>';if(op.kind==='contract_create'&&!op.signature)return '<span class="badge warn">'+(op.pc_received?'Reçu sur le PC · ':'')+'Signature attendue</span>';return '<span class="badge warn">En ligne · confirmation PC attendue</span>'}
function pendingFor(id){const o=opFor(id);return o&&(!o.status||o.status==='pending')}
function identity(kind){return kind.startsWith('client')||kind==='vehicle_update'?'code':kind==='contract_create'?'numero':'reference'}
function collection(kind){return kind.startsWith('client')?'clients':kind==='vehicle_update'?'vehicles':kind.startsWith('reservation')?'reservations':kind.startsWith('maintenance')?'maintenance':'contracts'}
function overlay(d,q){for(const o of q){if(o.kind==='document_upload')continue;let key=collection(o.kind),id=identity(o.kind);d[key]=d[key].filter(r=>r[id]!==o.record[id]);d[key].push(o.record)}return d}
let saving=Promise.resolve();
function atomic(fn){let next=saving.then(async()=>{let copy=clone(state);await fn(copy);await GP.set('state',copy);state=copy;render()});saving=next.catch(()=>{});return next}
async function enqueue(kind,record,extra={}){const op={id:GP.uid('op'),kind,record,...extra};await atomic(s=>{s.queue.push(op);overlay(s.data,[op]);if(kind==='contract_create')s.archives[record.numero]=op});toast('Enregistré sur le téléphone.');if(navigator.onLine&&state.config?.token)setTimeout(()=>sync(false),300);return op}
function metrics(items){return `<div class="grid">${items.map(([label,value,cls])=>`<div class="metric ${cls||''}"><small>${label}</small><b>${value}</b></div>`).join('')}</div>`}
const iconPaths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',clients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',vehicles:'m5 7 2-4h10l2 4M3 8h18v11H3zM6 19v2M18 19v2M6 12h2M16 12h2',contracts:'M8 4H5v18h14V4h-3M9 2h6v4H9zM8 11h8M8 15h8M8 19h5',reservations:'M3 5h18v16H3zM7 2v6M17 2v6M3 10h18M7 14h2M13 14h2',finance:'M3 21h18M6 17v-6M12 17V3M18 17V7',sync:'M20 7a8 8 0 0 0-14-2L3 8M3 3v5h5M4 17a8 8 0 0 0 14 2l3-3M16 16h5v5',more:'M3 6h18M3 12h18M3 18h18'};
function uiIcon(name){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.contracts}"/></svg>`}
function render(){if(!state)return;document.body.classList.toggle('connection-page',!state.config?.token);document.getElementById('company').textContent=data().settings.company_name||'HAJ BEN ZIAN CAR';const tabs=[['home','Accueil'],['clients','Clients'],['contracts','Contrats'],['vehicles','Véhicules']];document.getElementById('nav').innerHTML=tabs.map(([id,text])=>`<button class="${tab===id?'active':''}" data-action="tab" data-id="${id}">${uiIcon(id)}${text}</button>`).join('')+`<button data-action="menu">${uiIcon('more')}Plus</button>`;
document.getElementById('drawer-links').innerHTML=[['home','Tableau de bord'],['clients','Clients'],['vehicles','Véhicules'],['contracts','Contrats'],['rentals','Table de location'],['reservations','Réservations'],['finance','Finances'],['sync','Synchronisation']].map(([id,label])=>`<button data-action="tab" data-id="${id}" class="${tab===id?'selected':''}">${uiIcon(id)}${label}</button>`).join('')+`<button data-action="settings">${uiIcon('more')}Paramètres et sauvegarde</button><a href="${websiteURL}" target="_blank" rel="noopener">${uiIcon('home')}Site web</a>`;
if(!state.config?.token){connectionView();return}if(tab==='home')home();else if(tab==='clients')clientsView();else if(tab==='vehicles')vehiclesView();else if(tab==='contracts')contractsView();else if(tab==='rentals')rentalsView();else if(tab==='reservations')reservationsView();else if(tab==='finance')financeView();else syncView()}
function connectionView(){main.innerHTML=`<section class="connection"><div class="connection-intro">${uiIcon('vehicles')}<h1>Gestion Pro</h1><p>Location de voitures</p><small>Simple · Rapide · Professionnel</small></div><form id="connection-form" class="card"><h2>Connexion à votre agence</h2><p class="muted">Utilisez votre clé Android de connexion.</p>${input('token','Clé Android','','password','required autocomplete="off"')}<button type="submit">Se connecter →</button><p class="connection-foot">PC · Android · Synchronisé</p></form></section>`;document.getElementById('connection-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('button');submit.disabled=true;try{const token=new FormData(e.target).get('token').trim();const response=await fetch('/mobile/api/sync',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({operations:[]}),cache:'no-store'});if(!response.ok)throw Error('Clé refusée ou connexion indisponible. Vérifiez votre clé Android.');await atomic(st=>{st.config={token}});await sync();}catch(x){toast(x.message);submit.disabled=false;}}}
function syncHint(){return data().pc_at?'Dernières données du PC : '+new Date(data().pc_at*1000).toLocaleString('fr-FR'):'Première synchronisation PC nécessaire pour charger le parc et les données existantes.'}
function dashboardItems(){const today=GP.isoToday(),next=new Date(today+'T12:00:00');next.setDate(next.getDate()+1);const tomorrow=next.getFullYear()+'-'+String(next.getMonth()+1).padStart(2,'0')+'-'+String(next.getDate()).padStart(2,'0');const reservations=data().reservations.filter(r=>!GP.closed(r.status)&&GP.iso(r.end_date)>=today);const rented=data().contracts.filter(r=>!GP.closed(r.return_status)&&GP.iso(r.date_depart)<=today&&(GP.iso(r.actual_return_date||r.date_retour)>=today||/RETARD CONFIRM/.test(r.return_status||'')));const free=day=>data().vehicles.filter(v=>v.service===1&&!data().contracts.some(r=>r.vehicle_code===v.code&&!GP.closed(r.return_status)&&GP.iso(r.date_depart)<=day&&(GP.iso(r.actual_return_date||r.date_retour)>=day||/RETARD CONFIRM/.test(r.return_status||'')))&&!data().reservations.some(r=>GP.vehicleCode(r)===v.code&&!GP.closed(r.status)&&GP.iso(r.start_date)<=day&&GP.iso(r.end_date)>=day));const pending=Array.from(new Map(operations().filter(o=>o.status!=='applied'&&o.status!=='rejected').map(o=>[o.id,o])).values());const pendingRefs=new Set(pending.map(o=>o.record.reference));const unconfirmed=reservations.filter(r=>!pendingRefs.has(r.reference)&&!/CONFIRM/.test(String(r.status||'').toUpperCase()));return {today,tomorrow,availableToday:free(today),availableTomorrow:free(tomorrow),reservations,rented,pending,unconfirmed}}
function dashboardCards(d){return `<div class="dashboard-cards">${[['availableToday','Disponibles aujourd’hui',d.availableToday.length,'green','vehicles'],['availableTomorrow','Disponibles demain',d.availableTomorrow.length,'blue','vehicles'],['reservations','Réservations',d.reservations.length,'amber','reservations'],['rented','Véhicules en location',new Set(d.rented.map(r=>r.vehicle_code)).size,'pink','contracts'],['pending','À confirmer',d.pending.length+d.unconfirmed.length,'purple','sync']].map(([id,label,count,color,icon])=>`<button type="button" class="metric dashboard-card ${color}" data-action="dashboard-details" data-id="${id}">${uiIcon(icon)}<small>${label}</small><b>${count}</b><span>Voir les détails ›</span></button>`).join('')}</div>`}
function dashboardDetails(id){const d=dashboardItems();const labels={availableToday:'Disponibles aujourd’hui',availableTomorrow:'Disponibles demain',reservations:'Réservations',rented:'Véhicules en location',pending:'À confirmer'};let html='';if(id==='availableToday'||id==='availableTomorrow'){html=`<p class="muted">${GP.french(id==='availableToday'?d.today:d.tomorrow)} · Disponibilité sur la journée, selon les contrats et réservations synchronisés.</p>`+d[id].map(v=>`<section class="card">${vehicleImage(v)}<h3>${esc(v.modele)}</h3><p>${money(v.prix)} / jour</p>${button('Consulter le véhicule','vehicle',v.code,'secondary')}</section>`).join('');if(!d[id].length)html+='<p class="empty">Aucun véhicule disponible.</p>'}else if(id==='reservations'){html=d.reservations.map(r=>`<section class="card"><h3>${esc(r.reference)}</h3><p>${esc(r.last_name||r.client)} ${esc(r.first_name||'')}<br>${esc(r.vehicle_model||vehicle(GP.vehicleCode(r))?.modele||r.vehicle)}<br>${GP.french(r.start_date)} ${esc(r.start_time||'')} → ${GP.french(r.end_date)} ${esc(r.end_time||'')}</p><span class="badge">${esc(r.status||'À confirmer')}</span>${button('Consulter la réservation','reservation',r.reference,'secondary')}</section>`).join('')}else if(id==='rented'){html=sortedContracts(d.rented).map(r=>`<section class="card"><h3>${esc(vehicle(r.vehicle_code)?.modele||r.vehicle_code)}</h3><p>${esc(client(r.client_code)?.nom||r.client_code)} ${esc(client(r.client_code)?.prenom||'')}<br>${GP.french(r.date_depart)} ${esc(r.heure_depart||'')} → ${GP.french(r.date_retour)} ${esc(r.heure_retour||'')}</p>${badge(r.numero)}${button('Consulter le contrat','contract',r.numero,'secondary')}</section>`).join('')}else if(id==='pending'){html=d.pending.map(o=>{const r=o.record,key=r.numero||r.reference||r.code;const action=o.kind.startsWith('client')?'client':o.kind==='contract_create'?'contract':o.kind.startsWith('reservation')?'reservation':o.kind==='vehicle_update'?'vehicle':'edit-maintenance';return `<section class="card"><h3>${esc(key)}</h3>${badge(key)}${button('Consulter le dossier',action,key,'secondary')}</section>`}).join('')+d.unconfirmed.map(r=>`<section class="card"><h3>${esc(r.reference)}</h3><p>${esc(r.client)} · ${esc(r.status||'À confirmer')}</p>${button('Consulter la réservation','reservation',r.reference,'secondary')}</section>`).join('')}show(labels[id]||'Détails',html||'<p class="empty">Aucun dossier dans cette catégorie.</p>')}
function maintenanceAlerts(){const result=[];const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();for(const v of data().vehicles.filter(v=>v.service===1)){for(const [key,label,limit] of [['vidange','Vidange',1000],['adblue','AdBlue',2000],['chaine','Chaîne',5000]]){const jobs=data().maintenance.filter(m=>GP.vehicleCode(m)===v.code&&norm(m.service).replace(/[^a-z]/g,'').includes(key)).sort((a,b)=>GP.iso(b.date).localeCompare(GP.iso(a.date))||Number(b.mileage)-Number(a.mileage));const job=jobs[0],due=Number(job?.next_mileage||v['prochaine_'+key]),remaining=due-Number(v.compteur);if(due>0&&remaining<=limit)result.push({code:v.code,model:v.modele,label,limit,due,remaining,key:v.code+'|'+key+'|'+due})}}for(const v of data().vehicles.filter(v=>v.service===1)){for(const [field,label] of [['assurance_fin','Assurance'],['controle_technique','Visite technique']]){const date=GP.iso(v[field]);if(!/^\d{4}-\d{2}-\d{2}$/.test(date))continue;const days=Math.round((Date.parse(date+'T00:00:00Z')-Date.parse(GP.isoToday()+'T00:00:00Z'))/86400000);if(Number.isFinite(days)&&days<8)result.push({code:v.code,model:v.modele,label,remaining:days,unit:'jours',date,key:v.code+'|'+field+'|'+date})}}return result.sort((a,b)=>a.remaining-b.remaining)}
function maintenanceAlertText(a){const unit=a.unit||'km';return a.remaining<0?'Échéance dépassée de '+Math.abs(a.remaining)+' '+unit:a.remaining===0?'À effectuer maintenant':a.remaining+' '+unit+' restants'}
function maintenanceAlertCard(){const alerts=maintenanceAlerts();return `<section class="card"><div class="section-head"><h2>Entretiens à prévoir · ${alerts.length}</h2>${button('Activer les notifications','enable-maintenance-notifications','','secondary small-btn')}</div><p class="finance-hint">Vidange ≤ 1 000 km · AdBlue ≤ 2 000 km · Chaîne ≤ 5 000 km · Assurance et visite technique : moins de 8 jours. Vérification à l’ouverture et après synchronisation.</p>${alerts.map(a=>`<div class="note maintenance-danger"><b>${esc(a.model)} · ${a.label}</b><br>${maintenanceAlertText(a)}${a.date?' · '+GP.french(a.date):''}${button('Consulter les interventions','vehicle',a.code,'secondary small-btn')}</div>`).join('')||'<p class="muted">Aucune alerte kilométrique selon les échéances renseignées.</p>'}</section>`}
let maintenanceNotifying=false;
async function notifyMaintenance(){if(maintenanceNotifying||!state?.maintenanceNotifications||!('Notification'in window)||Notification.permission!=='granted')return;maintenanceNotifying=true;try{const registration=await navigator.serviceWorker.ready;const sent={...(state.maintenanceNotified||{})};let changed=false;for(const a of maintenanceAlerts()){const stage=a.remaining<=0?'due':'soon',marker=GP.isoToday()+'|'+stage;if(sent[a.key]===marker)continue;await registration.showNotification('Gestion Pro · '+a.label,{body:a.model+' : '+maintenanceAlertText(a)+'. Ouvrez la fiche véhicule.',icon:'/mobile/icon-192.png',tag:'maintenance-'+a.key,data:{vehicle:a.code}});sent[a.key]=marker;changed=true}if(changed)await atomic(st=>st.maintenanceNotified=sent)}catch(x){toast('Notifications indisponibles. Les alertes restent visibles sur le tableau de bord.')}finally{maintenanceNotifying=false}}
function home(){const d=dashboardItems();
main.innerHTML=`<h1>Bonjour Saïd</h1><p class="subtitle">${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p><section class="card hero"><div class="status-line"><span class="badge ${navigator.onLine?'':'warn'}">${navigator.onLine?'● Connexion disponible':'⌁ Hors connexion'}</span>${button('↻ Synchronisation','tab','sync','secondary small-btn')}</div><p class="finance-hint">Données conservées sur ce téléphone.<br>${esc(syncHint())}</p></section>${dashboardCards(d)}${maintenanceAlertCard()}<section class="card"><h2>Actions rapides</h2><div class="grid actions">${button('♙ Nouveau client','new-client')}${button('▤ Créer un contrat','new-contract','','teal')}${button('▦ Nouvelle réservation','new-reservation','','secondary')}${button('◈ Situation financière','tab','finance','secondary')}</div></section>${siteLinks()}<section class="card"><div class="section-head"><h2>Derniers contrats</h2>${button('Voir tout','tab','contracts','secondary small-btn')}</div>${sortedContracts(data().contracts).slice(0,3).map(r=>`<div class="card"><h3>${esc(vehicle(r.vehicle_code)?.modele||r.vehicle_code)}</h3><p>${esc(client(r.client_code)?.nom||r.client_code)} · ${GP.french(r.date_depart)} → ${GP.french(r.date_retour)}</p><p>Départ : ${esc(r.km_depart??'—')} km</p>${badge(r.numero)}</div>`).join('')||'<p class="empty">Aucun contrat enregistré.</p>'}</section>`}
function searchBox(placeholder){return `<input class="search" id="search" aria-label="Rechercher" placeholder="${placeholder}" value="${esc(search)}">`}
function match(r){return Object.values(r).join(' ').toLocaleLowerCase().includes(search.toLocaleLowerCase())}
function clientMatches(r){const normal=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const fields=[r.code,r.nom,r.prenom,r.cin,r.telephone].map(normal);const query=normal(search).trim();if(!query)return false;const compact=query.replace(/[^a-z0-9]/g,'');if(compact&&fields.some(v=>v.replace(/[^a-z0-9]/g,'').includes(compact)))return true;return query.split(/\s+/).every(word=>fields.some(v=>v.includes(word)))}
function clientsView(){main.innerHTML=`<div class="section-head"><h1>Clients</h1>${button('＋ Ajouter','new-client','','small-btn')}</div>${searchBox('Code, CIN, nom, prénom ou téléphone')}<div id="results">${(search.trim()?data().clients.filter(clientMatches):[]).map(r=>`<article class="card"><button class="list-button" data-action="client" data-id="${esc(r.code)}"><span class="avatar">${esc((r.nom||'?')[0]+(r.prenom||' ')[0])}</span><span><b>${esc(r.nom+' '+r.prenom)}</b><small>${esc(r.code)} · CIN ${esc(r.cin)}</small><small>${esc(r.telephone)}</small></span><span class="chev">›</span></button></article>`).join('')||`<p class="empty">${search.trim()?'Aucun client correspondant.':'Saisissez le code, le nom, le prénom, la CIN ou le téléphone pour afficher un client.'}</p>`}</div>`}
function siteLinks(c=null){let phone='';try{phone=GPDoc.phone(c?.telephone)}catch(x){}const message='Bonjour '+(c?(c.prenom||c.nom):'')+', voici le site de Haj Ben Zian Car pour consulter nos véhicules et demander une réservation : '+websiteURL;return `<section class="card"><h3>Site web de la société</h3><div class="actions"><a class="button secondary" href="${websiteURL}" target="_blank" rel="noopener">Ouvrir le site web</a>${button('Copier le lien du site','copy-site-link','','secondary')}${phone?`<a class="button whatsapp" href="https://wa.me/${phone}?text=${encodeURIComponent(message)}" target="_blank" rel="noopener">Envoyer le site au client par WhatsApp</a><p class="finance-hint">Téléphone de la fiche client : ${esc(c.telephone)}</p>`:c?'<p class="note">Renseignez un numéro de téléphone valide dans la fiche client pour envoyer le lien par WhatsApp.</p>':''}</div></section>`}
async function copyWebsiteLink(){try{await navigator.clipboard.writeText(websiteURL);toast('Lien du site copié.')}catch(x){const box=document.createElement('dialog');box.innerHTML='<h3>Copier le lien du site</h3><p>Maintenez le doigt sur le lien sélectionné puis choisissez Copier.</p><input readonly aria-label="Lien du site"><button type="button" class="secondary">Fermer</button>';box.querySelector('input').value=websiteURL;document.body.append(box);box.querySelector('button').onclick=()=>box.close();box.onclose=()=>box.remove();box.showModal();box.querySelector('input').select();}}
function clientDetail(code){const r=client(code);if(!r)return;show('Fiche client',`<div class="profile-head"><span class="avatar">${esc((r.nom||'?')[0]+(r.prenom||' ')[0])}</span><div><span class="badge">${esc(r.code)}</span><h2>${esc(r.nom+' '+r.prenom)}</h2><small>${esc(r.telephone)}</small></div></div><div class="detail-fields">${[['CIN',r.cin],['Adresse',[r.adresse,r.ville].filter(Boolean).join(' · ')],['Téléphone',r.telephone],['Naissance',GP.french(r.date_naissance)],['N° de permis',r.permis],['Date d’obtention',GP.french(r.date_permis)]].map(([label,value])=>`<div><small>${label}</small><b>${esc(value||'—')}</b></div>`).join('')}</div>${badge(code)}<div class="actions">${button('✎ Modifier','edit-client',code,'secondary')}${button('▤ Établir un contrat','client-contract',code,'teal')}${button('▦ Réserver','client-reservation',code,'secondary')}</div>${clientPDFs(code)}${siteLinks(r)}<h2 style="margin-top:24px">Historique des contrats</h2>${sortedContracts(data().contracts.filter(c=>c.client_code===code)).map(c=>`<section class="card"><h3>${esc(c.numero)}</h3><p>${GP.french(c.date_depart)} · ${money(c.montant)}</p>${badge(c.numero)}${button('Consulter / PDF','contract',c.numero,'secondary small-btn')}</section>`).join('')||'<p class="muted">Aucun contrat.</p>'}`)}
function clientPDFs(code){const docs=Array.from(new Map(operations().filter(o=>o.kind==='document_upload'&&o.record.client_code===code).map(o=>[o.id,o])).values());return `<section class="card"><h3>Documents PDF</h3>${button('＋ Insérer un document PDF','insert-client-pdf',code,'secondary')}${button('Consulter les documents','client-documents',code,'secondary')}<p class="finance-hint">Après synchronisation, le PDF apparaît dans « Autres documents » du client sur le PC, accessible depuis la table clients et la fiche client.</p>${docs.map(o=>`<div class="pdf-document"><b>${esc(o.record.filename)}</b><p>${o.status==='applied'?'✓ Stocké dans les documents PDF du PC':o.status==='rejected'?'À corriger : '+esc(o.message):'Enregistré sur le téléphone · transfert PC en attente'}</p>${button('Consulter le PDF','open-client-pdf',o.id,'secondary small-btn')}${o.status==='rejected'?`<p class="note">Mettez à jour le synchroniseur du PC avec INSTALLER_PC, puis relancez le transfert.</p>${button('Réessayer le transfert vers le PC','retry-client-pdf',o.id,'teal')}`:''}</div>`).join('')}</section>`}
function insertClientPDF(code){const picker=document.createElement('input');picker.type='file';picker.accept='application/pdf,.pdf';picker.hidden=true;document.body.append(picker);picker.onchange=async()=>{try{const file=picker.files[0];if(!file)return;if(file.size>2000000)throw Error('PDF trop volumineux : maximum 2 Mo.');const bytes=new Uint8Array(await file.arrayBuffer());if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw Error('Choisissez un document PDF valide.');await enqueue('document_upload',{reference:GP.uid('PDF'),client_code:code,filename:file.name},{pdf:GPDoc.toBase64(bytes)});clientDetail(code);toast('PDF conservé sur le téléphone. Transfert vers le PC à la prochaine synchronisation.');}catch(x){toast(x.message)}finally{picker.remove()}};picker.oncancel=()=>picker.remove();picker.click()}
function clientForm(code='',seed=null){const old=client(code);if(code&&pendingFor(code)){toast('Attendez la confirmation PC avant de modifier cette fiche.');return}const r=old||seed||{};show(old?'Modifier le client':'Nouveau client',`<form id="client-form"><p class="muted">Code ${old?esc(code):'automatique et unique sur ce téléphone'}</p><div class="form-grid">${input('nom','Nom *',r.nom,'text','required maxlength="100"')}${input('prenom','Prénom',r.prenom)}${input('cin','CIN *',r.cin,'text','required maxlength="60"')}${input('telephone','Téléphone',r.telephone,'tel')}${input('date_naissance','Date de naissance',GP.iso(r.date_naissance),'date')}${input('ville','Ville',r.ville)}${input('permis','N° permis',r.permis)}${input('date_permis','Date du permis',GP.iso(r.date_permis),'date')}${input('categorie','Catégorie',r.categorie)}${input('validite_permis','Validité du permis',GP.iso(r.validite_permis),'date')}<label class="full">Adresse<textarea name="adresse">${esc(r.adresse)}</textarea></label></div><button class="teal" type="submit">✓ Enregistrer</button></form>`);document.getElementById('client-form').onsubmit=async e=>{e.preventDefault();try{let form=Object.fromEntries(new FormData(e.target));let record=GP.cleanClient({...form,code:old?code:GP.uid('MCL')});if(data().clients.some(c=>c.code!==record.code&&c.cin.trim().toUpperCase()===record.cin.trim().toUpperCase()))throw Error('Cette CIN est déjà enregistrée.');for(const k of ['date_naissance','date_permis','validite_permis'])if(record[k])record[k]=GP.french(record[k]);await enqueue(old?'client_update':'client_create',record,old?{original:clone(old)}:{});dialog.close();route('clients')}catch(x){toast(x.message)}}}
function brandName(v){const model=(v.modele||'').toLowerCase();return ['peugeot','dacia','citroen','volkswagen','opel','renault'].find(b=>model.normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(b))||(/208/.test(model)?'peugeot':/celys/.test(model)?'citroen':/t.?roc/.test(model)?'volkswagen':/corsa/.test(model)?'opel':/stepway|sandero|logan/.test(model)?'dacia':'')}
function vehicleImage(v){const brand=brandName(v),logo=v.brand_logo_uri||(brand?'/mobile/brands/'+brand+(['peugeot','dacia'].includes(brand)?'.png':'.svg'):'');return `<div class="vehicle-media">${v.photo_uri?`<img class="vehicle-photo" src="${esc(v.photo_uri)}" alt="Photo ${esc(v.modele)}">`:'<div class="photo-missing">Photo à renseigner sur le PC</div>'}${logo?`<img class="brand-logo" src="${esc(logo)}" alt="Logo ${esc(brand||'de la marque')}">`:''}</div>`}
function vehiclesView(){main.innerHTML=`<h1>Véhicules</h1><p class="subtitle">Notre parc en service</p>${searchBox('Rechercher une marque ou un véhicule')}<div class="vehicle-list">${data().vehicles.filter(r=>r.service===1&&match(r)).map(r=>`<article class="card">${vehicleImage(r)}<h3>${esc(r.modele)}</h3><p>${money(r.prix)} / jour</p>${button('Consulter','vehicle',r.code,'secondary')}</article>`).join('')||'<p class="empty">Synchronisez le PC pour charger le parc.</p>'}</div>`}
function vehicleDetail(code){const r=vehicle(code);if(!r)return;const jobs=data().maintenance.filter(m=>GP.vehicleCode(m)===code);let latestJobs=Object.values(jobs.slice().sort((a,b)=>GP.iso(b.date).localeCompare(GP.iso(a.date))||Number(b.mileage)-Number(a.mileage)).reduce((all,m)=>{all[m.service]??=m;return all},{}));let alerts=latestJobs.filter(m=>Number(m.next_mileage)>0&&Number(m.next_mileage)<=Number(r.compteur)||m.next_date&&GP.iso(m.next_date)<=GP.isoToday());show(r.modele,`${vehicleImage(r)}${metrics([['Tarif journalier',money(r.prix),'green']])}<p>${badge(code)}</p><div class="actions">${button('✎ Modifier le compteur','counter',code,'secondary')}${button('＋ Entretien','new-maintenance',code,'teal')}</div>${alerts.length?'<p class="note">'+alerts.length+' entretien(s) arrivé(s) à échéance. Vérifiez les interventions les plus récentes.</p>':''}<h2 style="margin-top:24px">Table des entretiens</h2><div class="table-wrap"><table><thead><tr><th>Intervention</th><th>Date / Km</th><th>Prochaine échéance</th><th>Coût</th><th>Action</th></tr></thead><tbody>${jobs.slice().sort((a,b)=>GP.iso(b.date).localeCompare(GP.iso(a.date))).map(m=>`<tr><td>${esc(m.service)}<br><small>${esc(m.reference)}</small></td><td>${GP.french(m.date)}<br>${esc(m.mileage)} km</td><td>${m.next_mileage?esc(m.next_mileage)+' km<br>Restant : '+Math.max(0,Number(m.next_mileage)-Number(r.compteur))+' km':'—'}${m.next_date?'<br>'+GP.french(m.next_date):''}</td><td>${money(m.amount)}</td><td>${button('Modifier','edit-maintenance',m.reference,'secondary small-btn')}</td></tr>`).join('')||'<tr><td colspan="5">Aucun entretien enregistré.</td></tr>'}</tbody></table></div>`)}
function counterForm(code){const r=vehicle(code);if(!r)return;if(pendingFor(code)){toast('Le compteur attend sa confirmation PC.');return}show('Mettre à jour le kilométrage',`<form id="counter-form"><h3>${esc(r.modele)}</h3><p>Compteur enregistré : ${r.compteur} km</p>${input('compteur','Kilométrage actuel *',r.compteur,'number',`required min="${r.compteur}" step="1"`)}<button class="teal">Enregistrer le compteur</button></form>`);document.getElementById('counter-form').onsubmit=async e=>{e.preventDefault();try{let km=Number(new FormData(e.target).get('compteur'));if(!Number.isSafeInteger(km)||km<Number(r.compteur))throw Error('Le compteur doit être un entier et ne peut pas diminuer.');await enqueue('vehicle_update',{...r,compteur:km},{original:clone(r)});vehicleDetail(code)}catch(x){toast(x.message)}}}
function maintenanceForm(code,ref='',seed=null){const old=data().maintenance.find(r=>r.reference===ref);if(old&&pendingFor(ref)){toast('Attendez la confirmation PC avant de modifier cet entretien.');return}const r=old||seed||{},v=vehicle(code||GP.vehicleCode(r));if(!v)return;show(old?'Modifier l’entretien':'Nouvel entretien',`<form id="maintenance-form"><h3>${esc(v.modele)} · ${v.compteur} km actuels</h3><div class="form-grid">${select('service','Type d’entretien',[...new Set(['Vidange','AdBlue','Chaîne','Courroie','Freins','Pneus','Batterie','Autre',r.service].filter(Boolean))].map(s=>[s,s]),r.service||'Vidange')}${input('date','Date *',GP.iso(r.date)||GP.isoToday(),'date','required')}${input('mileage','Kilométrage de l’intervention *',r.mileage??v.compteur,'number','required min="0" step="1"')}${input('next_mileage','Prochaine intervention (km)',r.next_mileage,'number','min="0" step="1"')}${input('next_date','Prochaine intervention (date)',GP.iso(r.next_date),'date')}${input('amount','Coût (DH)',r.amount||0,'number','min="0" step="0.01"')}${input('supplier','Fournisseur / garage',r.supplier)}${select('payment_method','Règlement',[['ESPÈCES','Espèces'],['BANQUE','Banque'],['CHÈQUE','Chèque']],r.payment_method||'ESPÈCES')}${input('product','Produit',r.product)}${input('quantity','Quantité',r.quantity||'1','number','min="0" step="0.01"')}<label class="full">Observations<textarea name="notes">${esc(r.notes)}</textarea></label></div><button class="teal">✓ Enregistrer l’entretien</button></form>`);document.getElementById('maintenance-form').onsubmit=async e=>{e.preventDefault();try{const p=Object.fromEntries(new FormData(e.target));let km=GP.num(p.mileage),next=p.next_mileage?GP.num(p.next_mileage):0;if(!Number.isSafeInteger(km)||next&&!Number.isSafeInteger(next)||next&&next<km)throw Error('Kilométrage ou échéance invalide.');const record={...r,...p,reference:old?ref:GP.uid('MENT'),vehicle:v.code+' | '+v.modele+' | '+v.immatriculation,date:GP.french(p.date),next_date:p.next_date?GP.french(p.next_date):'',current_counter:String(v.compteur),mileage:String(km),next_mileage:next?String(next):'',remaining_km:next?String(Math.max(0,next-Number(v.compteur))):'',product_km:next?String(next-km):'',amount:GP.num(p.amount).toFixed(2),product_ref:r.product_ref||''};await enqueue(old?'maintenance_update':'maintenance_create',record,old?{original:clone(old)}:{});vehicleDetail(v.code)}catch(x){toast(x.message)}}}
function options(){return {clients:data().clients.map(c=>[c.code,c.code+' · '+c.nom+' '+c.prenom]),vehicles:data().vehicles.filter(v=>v.service===1).map(v=>[v.code,v.modele])}}
function defaultReturnDate(){const d=new Date(GP.isoToday()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10)}
function bookingForm(mode,code='',ref='',seed=null){const isReservation=mode==='reservation',old=isReservation?data().reservations.find(r=>r.reference===ref):null;if(old&&pendingFor(ref)){toast('Réservation en attente de confirmation PC.');return}if(!data().clients.length||!data().vehicles.length){toast('Ajoutez un client et chargez les véhicules par synchronisation PC.');return}const draftNumber=GP.uid('MCT');const opt=options(),r=old||seed||{},selected=code||String(r.client||'').split('|')[0].trim()||opt.clients[0][0];show(isReservation?(old?'Modifier la réservation':'Nouvelle réservation'):'Nouveau contrat',`<form id="booking-form"><div class="form-grid"><div class="full">${input('client_lookup','CIN ou code client','','text','autocomplete="off"')}<button type="button" id="find-client" class="secondary small-btn">Rechercher le client</button><p id="lookup-feedback" role="status"></p>${select('client_code','Client *',opt.clients,selected)}<div id="client-summary" class="field-read"></div></div><div class="full">${select('vehicle_code','Véhicule en service *',opt.vehicles,GP.vehicleCode(r)||opt.vehicles[0][0])}</div>${input('start','Date de départ *',GP.iso(r.start_date)||GP.isoToday(),'date','required')}${input('start_time','Heure de départ',r.start_time||'09:00','time','required')}${input('end','Date de retour *',GP.iso(r.end_date)||defaultReturnDate(),'date','required')}${input('end_time','Heure de retour',r.end_time||'09:00','time','required')}${input('price','Tarif / jour (DH) *',r.daily_price||'','number','required min="0" step="0.01"')}${input('paid',isReservation?'Acompte reçu (DH)':'Règlement reçu (DH)',r.deposit||0,'number','min="0" step="0.01"')}${isReservation?select('status','Statut',[['EN ATTENTE','En attente'],['CONFIRMÉ','Confirmé'],['PAYÉ','Payé'],['ANNULÉ','Annulé'],['TERMINÉ','Terminé']],({'CONFIRMEE':'CONFIRMÉ','ANNULEE':'ANNULÉ','TERMINEE':'TERMINÉ'}[r.status]||r.status||'EN ATTENTE')):`<label>Kilométrage actuel<div id="current-km" class="field-read"></div></label>${input('km','Kilométrage de départ *','','number','required min="0" step="1"')}`}<label class="full">Observations<textarea name="notes">${esc(r.notes)}</textarea></label></div><div id="quote" class="total"></div><p class="note">Disponibilité basée sur les dernières données connues. Confirmation définitive après contrôle sur le PC.</p>${isReservation?'':`<section class="card"><h3>Conditions du contrat</h3><p style="white-space:pre-wrap">${esc(data().settings.general_conditions||'Configurez les conditions de la société avant signature.')}</p>${button('Consulter le PDF avant signature','preview-draft','','secondary')}<h3 style="margin-top:20px">Signature du client</h3><canvas id="signature" class="signature"></canvas><div class="sig-tools">${button('Effacer','clear-signature','','secondary small-btn')}</div><label><input name="agree" type="checkbox" style="width:auto"> Le client a lu le recto et le verso du contrat et accepte ses conditions.</label>${select('sign_mode','Signature',[['local','Signer sur ce téléphone'],['remote','Envoyer un lien pour signature à distance']],'local')}</section>`}<p id="booking-status" role="status" aria-live="polite"></p><button id="save-booking" class="teal" type="submit">✓ ${isReservation?'Enregistrer la réservation':'Enregistrer le contrat sans signature'}</button>${isReservation?'':button('✓ Valider la signature et enregistrer','confirm-signature','','teal')}<p class="note">${isReservation?'':'Le contrat peut être enregistré avant signature. Pour produire le PDF signé, cochez l’acceptation et choisissez « Valider la signature et enregistrer ».'}</p></form>`);
const form=document.getElementById('booking-form');document.getElementById('find-client').onclick=()=>{const q=form.elements.client_lookup.value.trim().toLocaleUpperCase();const found=data().clients.filter(c=>[c.code,c.cin].some(v=>String(v||'').trim().toLocaleUpperCase()===q));const feedback=document.getElementById('lookup-feedback');if(found.length!==1){feedback.textContent=found.length?'Plusieurs fiches correspondent : choisissez le client.':'Client introuvable : vérifiez la CIN ou le code.';return}form.elements.client_code.value=found[0].code;selectedClient();feedback.textContent='Client sélectionné : '+found[0].nom+' '+found[0].prenom};form.elements.client_lookup.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();document.getElementById('find-client').click()}};if(!isReservation)pad=GPDoc.signature(document.getElementById('signature'));
function selectedVehicle(){const v=vehicle(form.elements.vehicle_code.value);form.elements.price.value=(old||seed)?r.daily_price:v.prix;if(!isReservation){document.getElementById('current-km').textContent=v.compteur+' km';form.elements.km.value=v.compteur;form.elements.km.min=v.compteur}recalc()}
function selectedClient(){const c=client(form.elements.client_code.value);document.getElementById('client-summary').textContent=[c.nom+' '+c.prenom,'CIN : '+c.cin,'Tél. : '+c.telephone].join(' · ')}
function recalc(){try{const q=GP.quote(form.elements.start.value,form.elements.end.value,form.elements.price.value,form.elements.paid.value,form.elements.start_time.value,form.elements.end_time.value);document.getElementById('quote').innerHTML=`<span>${q.days} jour(s)<br>Reste : ${money(q.balance)}</span><b>${money(q.total)}</b>`}catch(x){document.getElementById('quote').textContent=x.message}}
form.elements.vehicle_code.onchange=selectedVehicle;form.elements.client_code.onchange=selectedClient;form.oninput=recalc;selectedClient();selectedVehicle();
function draft(check=true){let p=Object.fromEntries(new FormData(form));let cl=client(p.client_code),v=vehicle(p.vehicle_code);let q=GP.quote(p.start,p.end,p.price,p.paid,p.start_time,p.end_time);if(check&&(!isReservation||!GP.closed(p.status)))GP.availability(data(),v.code,p.start,p.end,p.start_time,p.end_time,ref);if(isReservation)return {record:{...r,reference:old?ref:GP.uid('MRES'),status:p.status,client:cl.code,cin:cl.cin,phone:cl.telephone,last_name:cl.nom,first_name:cl.prenom,vehicle:v.code+' | '+v.modele+' | '+v.immatriculation,vehicle_model:v.modele,plate:v.immatriculation,start_date:GP.french(p.start),start_time:p.start_time,end_date:GP.french(p.end),end_time:p.end_time,duration:String(q.days),daily_price:GP.num(p.price).toFixed(2),total:q.total.toFixed(2),deposit:q.paid.toFixed(2),balance:q.balance.toFixed(2),notes:p.notes,booking_date:old?r.booking_date:GP.french(GP.isoToday())}};
if(!cl.cin||!cl.nom)throw Error('Complétez la CIN et le nom sur la fiche client avant d’établir le contrat.');let km=GP.num(p.km);if(!Number.isSafeInteger(km)||km<Number(v.compteur))throw Error('Le kilométrage de départ ne peut pas être inférieur au compteur actuel.');let record={numero:draftNumber,created_at:new Date().toISOString(),client_code:cl.code,vehicle_code:v.code,date_depart:GP.french(p.start),heure_depart:p.start_time,date_retour:GP.french(p.end),heure_retour:p.end_time,duree:q.days,prix:GP.num(p.price),montant:q.total,reglement:q.paid,reste:q.balance,km_depart:km,notes:p.notes,reservation_ref:mode==='contract'?ref:''};let frozen={record:clone(record),client:clone(cl),vehicle:clone(v),current_km:v.compteur,settings:clone(data().settings),created_at:new Date().toISOString()};return {record,frozen,mode:p.sign_mode}}
form.querySelector('[data-action="preview-draft"]')?.addEventListener('click',async()=>{try{let d=draft(false);previewPDF(await GPDoc.pdf(d.frozen,''),'Contrat avant signature')}catch(x){toast(x.message)}});
form.querySelector('[data-action="confirm-signature"]')?.addEventListener('click',()=>{if(!form.reportValidity())return;form.dataset.confirmSignature='yes';form.requestSubmit(document.getElementById('save-booking'))});
form.onsubmit=async e=>{e.preventDefault();if(form.dataset.saving==='yes')return;form.dataset.saving='yes';const submit=form.querySelector('[type=submit]'),status=form.querySelector('#booking-status'),confirmSign=form.dataset.confirmSignature==='yes';form.dataset.confirmSignature='';submit.disabled=true;try{let d=draft();if(isReservation){await enqueue(old?'reservation_update':'reservation_create',d.record,old?{original:clone(old)}:{});dialog.close();route('reservations');return}let ink='';if(confirmSign){if(d.mode!=='local')throw Error('Sélectionnez « Signer sur ce téléphone » pour valider cette signature.');ink=pad.value();if(!ink||!form.elements.agree.checked)throw Error('Tracez la signature et cochez l’acceptation du recto et du verso.');}await enqueue('contract_create',d.record,{frozen:d.frozen,signature:'',pdf:''});if(ink)await atomic(st=>{st.pendingSignatures=st.pendingSignatures||{};st.pendingSignatures[d.record.numero]={signature:ink,confirmed_at:new Date().toISOString()}});dialog.close();route('contracts');await sync(false);contractDetail(d.record.numero);const signed=archiveFor(d.record.numero)?.signature;body.insertAdjacentHTML('afterbegin',`<p class="badge ${ink&&!signed?'warn':''}">${signed?'✓ Contrat enregistré · Signature confirmée · PDF signé disponible':ink?'✓ Contrat enregistré sur le téléphone · Signature conservée, PDF à finaliser avec Internet':'✓ Contrat enregistré sur le téléphone · Signature attendue'}</p>`);}catch(x){status.textContent=x.message;status.className='note';toast(x.message);}finally{submit.disabled=false;form.dataset.saving=''}}}

function sortedContracts(rows){return rows.slice().sort((a,b)=>String(b.created_at||GP.iso(b.date_depart)).localeCompare(String(a.created_at||GP.iso(a.date_depart)))||String(b.numero).localeCompare(String(a.numero)))}
function rentalsView(){main.innerHTML=`<div class="section-head"><h1>Table de location</h1>${button('Contrats','tab','contracts','secondary')}</div>${searchBox('Client, véhicule ou contrat')}<section class="card"><div class="table-wrap"><table><thead><tr><th>Client</th><th>Véhicule</th><th>Départ</th><th>Retour</th><th>Contrat</th></tr></thead><tbody>${sortedContracts(data().contracts).filter(r=>match({...r,client:client(r.client_code)?.nom+' '+client(r.client_code)?.prenom,vehicle:vehicle(r.vehicle_code)?.modele})).map(r=>`<tr><td>${esc((client(r.client_code)?.nom||r.client_code)+' '+(client(r.client_code)?.prenom||''))}</td><td>${esc(vehicle(r.vehicle_code)?.modele||r.vehicle_code)}</td><td>${GP.french(r.date_depart)}<br>${esc(r.heure_depart||'')}</td><td>${GP.french(r.date_retour)}<br>${esc(r.heure_retour||'')}</td><td>${esc(r.numero)}<br>${badge(r.numero)}${button('Ouvrir','contract',r.numero,'secondary small-btn')}</td></tr>`).join('')||'<tr><td colspan="5">Aucune location.</td></tr>'}</tbody></table></div></section>`}
function contractsView(){main.innerHTML=`<div class="section-head"><h1>Contrats</h1><div>${button('Table de location','tab','rentals','secondary small-btn')}${button('＋ Contrat','new-contract','','small-btn')}</div></div>${searchBox('Client, code ou contrat')}<p class="finance-hint">Copies signées créées sur ce téléphone et contrats récupérés du PC.</p>${sortedContracts(data().contracts.filter(match)).map(r=>`<article class="card"><div class="section-head"><h3>${esc(vehicle(r.vehicle_code)?.modele||r.vehicle_code)}</h3><b>${money(r.montant)}</b></div><p>${esc(r.numero)}<br>${esc(client(r.client_code)?.nom||r.client_code)} · ${GP.french(r.date_depart)} → ${GP.french(r.date_retour)}</p><p>Compteur actuel : ${esc(vehicle(r.vehicle_code)?.compteur??'—')} km · Départ : ${esc(r.km_depart??'—')} km</p>${badge(r.numero)}<div style="margin-top:13px">${button('Consulter / Signature / PDF','contract',r.numero,'secondary')}</div></article>`).join('')||'<p class="empty">Aucun contrat.</p>'}`}
function archiveFor(id){const remote=(data().operations||[]).find(o=>o.kind==='contract_create'&&o.record.numero===id&&o.signature);return remote||state.archives[id]||(data().operations||[]).find(o=>o.kind==='contract_create'&&o.record.numero===id)}
function contractDetail(id){const r=data().contracts.find(c=>c.numero===id)||state.archives[id]?.record;if(!r)return;const a=archiveFor(id);show('Contrat de location',`<h3>${esc(id)}</h3><p>${esc(client(r.client_code)?.nom||r.client_code)}<br>${esc(vehicle(r.vehicle_code)?.modele||r.vehicle_code)}</p><p>Départ : ${GP.french(r.date_depart)} à ${esc(r.heure_depart||'')}<br>Retour : ${GP.french(r.date_retour)} à ${esc(r.heure_retour||'')}</p><p>Compteur actuel : ${esc(vehicle(r.vehicle_code)?.compteur??'—')} km<br>Kilométrage de départ : ${esc(r.km_depart??'—')} km</p>${metrics([['Total',money(r.montant),'green'],['Reste à recevoir',money(r.reste),'amber']])}<p>${badge(id)}</p><div class="actions">${button('Consulter avant signature','preview-contract',id,'secondary')}</div>${a?.signature?`<h3>✓ Signature confirmée — PDF signé disponible</h3><img class="signature-img" alt="Signature du client" src="${esc(a.signature)}"><div class="actions">${button('Consulter après signature','preview-signed',id,'secondary')}${button('↓ Télécharger PDF signé','pdf',id)}${button('Envoyer le contrat signé au client par WhatsApp','whatsapp-pdf',id,'whatsapp')}</div>`:a?`<p class="note">Signature attendue. Le contrat est transmis au PC avant signature. La copie signée sera ensuite rattachée au même contrat.</p>${button('Signer sur ce téléphone','sign-local',id,'teal')}${button('Copier / consulter le lien de signature','invite',id,'secondary')}${button('Envoyer le lien de signature par WhatsApp','invite-whatsapp',id,'whatsapp')}`:`<p class="note">Récupérez la copie signée conservée dans les archives du PC.</p>${button('Récupérer le contrat signé du PC','fetch-signed',id,'teal')}`}`)}
let calendarMonth=GP.isoToday().slice(0,7),calendarVehicle='';

function reservationCalendar(){const [year,m]=calendarMonth.split('-').map(Number),first=new Date(year,m-1,1),days=new Date(year,m,0).getDate(),offset=(first.getDay()+6)%7;const entries=[...data().reservations.map(r=>({id:r.reference,start:GP.iso(r.start_date),end:GP.iso(r.end_date),vehicle:GP.vehicleCode(r),status:r.status,action:'reservation',label:r.last_name||r.client})),...data().contracts.filter(r=>!GP.closed(r.return_status)).map(r=>({id:r.numero,start:GP.iso(r.date_depart),end:GP.iso(r.date_retour),vehicle:r.vehicle_code,status:'CONTRAT',action:'contract',label:client(r.client_code)?.nom||r.client_code}))].filter(r=>!calendarVehicle||r.vehicle===calendarVehicle);let cells='<div class="calendar-day empty"></div>'.repeat(offset);for(let d=1;d<=days;d++){const date=calendarMonth+'-'+String(d).padStart(2,'0');cells+=`<div class="calendar-day ${date===GP.isoToday()?'today':''}"><b>${d}</b>${entries.filter(r=>!GP.closed(r.status)&&r.start<=date&&r.end>=date).map(r=>`<button class="calendar-event ${r.status==='EN ATTENTE'?'pending':r.status==='CONTRAT'?'rental':'confirmed'}" data-action="${r.action}" data-id="${esc(r.id)}" title="${esc(r.id+' · '+r.status)}">${esc(vehicle(r.vehicle)?.modele||r.vehicle)}<small>${esc(r.label)}</small></button>`).join('')}</div>`}return `<section class="card"><div class="section-head"><h2>Planning du parc</h2>${button('‹','calendar-prev','','secondary small-btn')}${button('›','calendar-next','','secondary small-btn')}</div><div class="form-grid"><label>Mois<input type="month" id="calendar-month" value="${calendarMonth}"></label><label>Véhicule<select id="calendar-vehicle"><option value="">Tous les véhicules</option>${data().vehicles.map(v=>`<option value="${esc(v.code)}" ${v.code===calendarVehicle?'selected':''}>${esc(v.modele)}</option>`).join('')}</select></label></div><p class="finance-hint">Bleu : contrat · Vert : réservation confirmée · Orange : à confirmer. Touchez une entrée pour la consulter.</p><div class="calendar-scroll"><div class="calendar-grid">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(d=>`<strong>${d}</strong>`).join('')}${cells}</div></div></section>`}
function reservationsView(){main.innerHTML=`<div class="section-head"><h1>Réservations</h1>${button('＋ Réserver','new-reservation','','small-btn')}</div>${reservationCalendar()}${searchBox('Client, véhicule ou réservation')}${data().reservations.filter(match).slice().reverse().map(r=>`<article class="card"><h3>${esc(r.vehicle_model||vehicle(GP.vehicleCode(r))?.modele||r.vehicle)}</h3><p>${esc(r.last_name||r.client)} ${esc(r.first_name||'')}<br>${GP.french(r.start_date)} à ${esc(r.start_time)} → ${GP.french(r.end_date)} à ${esc(r.end_time)}</p><p><span class="badge ${GP.closed(r.status)?'warn':''}">${esc(r.status)}</span> · ${money(r.total)}<br>Acompte : ${money(r.deposit)} · Reste : ${money(r.balance)}</p>${badge(r.reference)}<div style="margin-top:12px">${button('✎ Consulter / Modifier','reservation',r.reference,'secondary')}${!GP.closed(r.status)?button('Établir un contrat','reservation-contract',r.reference,'teal'):''}</div></article>`).join('')||'<p class="empty">Aucune réservation.</p>'}`}
let financeMode='month',financeYear=String(new Date().getFullYear()),financeStart='',financeEnd='',financeRequest=0;
async function financeView(){const request=++financeRequest;if(!month)month=GP.isoToday().slice(0,7);let start='',end='';if(financeMode==='month'){start=month+'-01';let d=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0);end=month+'-'+String(d.getDate()).padStart(2,'0')}else if(financeMode==='year'){start=financeYear+'-01-01';end=financeYear+'-12-31'}else if(financeMode==='range'){start=financeStart;end=financeEnd}
main.innerHTML=`<h1>Finances</h1><section class="card"><label>Période<select id="finance-mode"><option value="month">Mois</option><option value="year">Année</option><option value="range">Dates personnalisées</option><option value="all">Toutes les dates</option></select></label>${financeMode==='month'?`<label>Mois<input id="finance-period" type="month" value="${esc(month)}"></label>`:financeMode==='year'?`<label>Année<input id="finance-period" type="number" min="2000" max="2100" value="${esc(financeYear)}"></label>`:financeMode==='range'?`<div class="form-grid"><label>Du<input id="finance-start" type="date" value="${esc(start)}"></label><label>Au<input id="finance-end" type="date" value="${esc(end)}"></label></div>`:''}<p class="finance-hint">Calculs de la synthèse Gestion Pro du PC. Les opérations mobiles en attente ne sont pas encore comptabilisées.</p></section><div id="finance-result" aria-live="polite">Chargement…</div>`;const select=document.getElementById('finance-mode');select.value=financeMode;select.onchange=e=>{financeMode=e.target.value;render()};const period=document.getElementById('finance-period');if(period)period.onchange=e=>{if(financeMode==='month')month=e.target.value;else financeYear=e.target.value;render()};for(const key of ['start','end']){const el=document.getElementById('finance-'+key);if(el)el.onchange=e=>{if(key==='start')financeStart=e.target.value;else financeEnd=e.target.value;render()}}
if(financeMode==='range'&&(!start||!end)){document.getElementById('finance-result').textContent='Choisissez les deux dates.';return}const cacheKey='finance:'+start+':'+end;let result=state.financialCache?.[cacheKey];let cached=true;try{const r=await fetch('/mobile/api/finance',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.config.token},body:JSON.stringify({start,end})});let j=await r.json();if(!r.ok)throw Error(j.error);result=j;cached=false;saving=saving.then(async()=>{state.financialCache=state.financialCache||{};state.financialCache[cacheKey]=result;await GP.set('state',state)});await saving}catch(x){if(!result){if(tab==='finance'&&request===financeRequest)document.getElementById('finance-result').textContent='Connectez-vous et synchronisez le PC pour charger cette période. '+x.message;return}}
if(tab!=='finance'||request!==financeRequest)return;const t=result.totals;document.getElementById('finance-result').innerHTML=`<p class="finance-hint">${cached?'Dernière synthèse conservée hors connexion. ':''}${result.pc_at?'Données PC du '+new Date(result.pc_at*1000).toLocaleString('fr-FR'):'Première synchronisation PC nécessaire.'}</p>${metrics([['Chiffre d’affaires',money(t.revenue),''],['Créances clients',money(t.receivables),'amber'],['Banque · mouvements nets',money(t.bank),'green'],['Caisse · mouvements nets',money(t.cash),'purple'],['Charges',money(t.expenses),'pink'],['Résultat',money(t.result),'green']])}<section class="card"><h2>Détail de la synthèse</h2><div class="table-wrap"><table><tbody>${[['Versements nets à la banque',t.versements],['Encaissements banque / chèques exécutés',t.client_cheques],['Charges réglées en caisse',t.charge_cash],['Charges réglées par banque / chèque',t.charge_cheques],['Dettes fournisseurs',t.supplier_payable],['Vision épargne',t.savings_future],['Débit',t.debit],['Crédit',t.credit],['Écart',t.balance_gap]].map(([label,n])=>`<tr><td>${label}</td><td>${money(n)}</td></tr>`).join('')}</tbody></table></div><p class="finance-hint">Banque et caisse suivent la synthèse PC sur la période choisie. Résultat = chiffre d’affaires − charges.</p></section><section class="card"><h2>Détails des opérations</h2>${[['revenue','Chiffre d’affaires'],['receivables','Créances'],['bank','Banque'],['cash','Caisse'],['expenses','Charges']].map(([key,label])=>`<details><summary>${label} · ${result.detail_counts?.[key]||0} ligne(s)</summary><div class="table-wrap"><table><thead><tr><th>Date</th><th>Référence</th><th>Client / organisme</th><th>Libellé</th><th>Montant</th><th>Statut</th></tr></thead><tbody>${(result.details?.[key]||[]).map(r=>`<tr>${r.slice(0,4).map(v=>`<td>${esc(v)}</td>`).join('')}<td>${money(r[4])}</td><td>${esc(r[5])}</td></tr>`).join('')||'<tr><td colspan="6">Aucun mouvement.</td></tr>'}</tbody></table></div>${(result.detail_counts?.[key]||0)>500?'<p>Les 500 premières lignes sont affichées ; la synthèse inclut toutes les opérations.</p>':''}</details>`).join('')}</section>`}

function syncView(){const ops=operations();main.innerHTML=`<h1>Synchronisation</h1><p class="subtitle">Le téléphone travaille même quand le PC est éteint.</p><section class="card hero"><span class="badge ${navigator.onLine?'':'warn'}">${navigator.onLine?'Connexion disponible':'Hors connexion'}</span><p>${esc(syncHint())}</p>${button(syncing?'Synchronisation…':'↻ Synchroniser maintenant','sync','','teal')}<p class="finance-hint">Dernier échange téléphone : ${state.lastSync?new Date(state.lastSync).toLocaleString('fr-FR'):'aucun'}</p></section>${metrics([['Sur le téléphone',state.queue.length,'amber'],['En attente du PC',ops.filter(o=>o.status==='pending').length,''],['Confirmées PC',ops.filter(o=>o.status==='applied').length,'green'],['À corriger',ops.filter(o=>o.status==='rejected').length,'pink']])}<section class="card"><h2>PC éteint ?</h2><p>Les changements envoyés sont conservés en ligne. Gestion Pro les récupère à sa prochaine ouverture. Les contrats et réservations restent provisoires jusqu’au contrôle du PC.</p></section><section class="card"><h2>Historique des échanges</h2>${ops.slice().reverse().map(o=>`<p><b>${esc(o.record.numero||o.record.reference||o.record.code)}</b><br>${esc(o.kind)}<br>${badge(o.record.numero||o.record.reference||o.record.code)}${o.status==='rejected'?button('Voir / Reprendre la saisie','op-recover',o.id,'secondary small-btn'):''}</p>`).join('')||'<p class="muted">Aucun échange.</p>'}</section>`}
async function sync(showMessage=true){if(syncing)return;if(!navigator.onLine){if(showMessage)toast('Pas de connexion. Vos données restent enregistrées.');return}if(!state.config?.token){if(showMessage)settings();return}syncing=true;if(tab==='sync')render();try{await saving;const queue=[];let batchBytes=0;for(const op of state.queue.slice(0,50)){const bytes=new TextEncoder().encode(JSON.stringify(op)).length;if(queue.length&&batchBytes+bytes>10000000)break;queue.push(clone(op));batchBytes+=bytes;}const response=await fetch('/mobile/api/sync',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.config.token},body:JSON.stringify({operations:queue}),cache:'no-store'});let incoming=await response.json();if(!response.ok)throw Error(incoming.error||'Échange impossible.');await atomic(s=>{const ack=new Set((incoming.operations||[]).map(o=>o.id));s.queue=s.queue.filter(o=>!ack.has(o.id));s.data=overlay(incoming,s.queue);for(const o of incoming.operations||[])if(o.kind==='contract_create'&&o.signature)s.archives[o.record.numero]={...s.archives[o.record.numero],...o};s.lastSync=new Date().toISOString()});await flushSignatures();await notifyMaintenance();if(showMessage)toast('Échange terminé. Les confirmations du PC sont affichées.')}catch(x){if(showMessage)toast(x.message)}finally{syncing=false;if(tab==='sync')render()}}
function settings(){show('Paramètres et sauvegarde',`<form id="settings-form"><p>Clé de connexion Android fournie lors de l’installation du relais.</p>${input('token','Clé Android',state.config?.token||'','password','autocomplete="off"')}<p class="finance-hint">Adresse du relais : ${esc(location.origin)}/mobile/</p><div class="actions"><button class="teal" type="submit">Enregistrer la connexion</button>${button('Installer l’application','install','','secondary')}</div></form><section class="card"><h3>Sauvegarde téléphone</h3><p class="finance-hint">Exportez une copie avant de changer de téléphone. Le fichier contient les données clients et les signatures ; conservez-le dans un endroit privé.</p><div class="actions">${button('Exporter la sauvegarde','backup','','secondary')}${button('Restaurer une sauvegarde','restore','','secondary')}</div><input id="restore-file" type="file" accept="application/json,.json" hidden></section><section class="card"><h3>Installation Android</h3><p>Dans Chrome : menu ⋮ → « Installer l’application » ou « Ajouter à l’écran d’accueil ». Ouvrez-la une première fois avec Internet, puis vous pourrez l’utiliser hors connexion.</p><p class="finance-hint">La synchronisation automatique se fait quand l’application est ouverte et connectée. Après fermeture, elle reprend à la prochaine ouverture.</p></section>`);document.getElementById('settings-form').onsubmit=async e=>{e.preventDefault();await atomic(s=>s.config={token:new FormData(e.target).get('token').trim()});dialog.close();await sync()};document.getElementById('restore-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const backup=JSON.parse(await file.text());if(backup.format!=='gestionpro-mobile-v1'||!backup.state?.data||!Array.isArray(backup.state.queue))throw Error('Sauvegarde non reconnue.');if(!confirm('Remplacer les données locales par cette sauvegarde ? Exportez d’abord vos changements récents.'))return;await GP.set('state',backup.state);state=backup.state;dialog.close();route('home');toast('Sauvegarde restaurée.')}catch(x){toast(x.message)}}}
async function invite(id,direct=false){let popup=null;try{let directPhone='';if(direct){const r=data().contracts.find(c=>c.numero===id)||archiveFor(id)?.record;directPhone=GPDoc.phone(client(r?.client_code)?.telephone||archiveFor(id)?.frozen?.client?.telephone);popup=window.open('about:blank','_blank');if(popup)popup.opener=null;}await sync(false);const op=(data().operations||[]).find(o=>o.record.numero===id);if(!op)throw Error('Connectez le téléphone pour envoyer le contrat au relais.');const response=await fetch('/mobile/api/invite',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.config.token},body:JSON.stringify({op_id:op.id})});let result=await response.json();if(!response.ok)throw Error(result.error);const url=location.origin+'/mobile/signature/'+result.token;if(direct&&popup){popup.location.href='https://wa.me/'+directPhone+'?text='+encodeURIComponent('Bonjour, merci de consulter et signer votre contrat de location '+id+' : '+url);toast('Lien de signature prêt dans WhatsApp. Validez l’envoi au client.');return}let phone='';try{phone=GPDoc.phone(client(op.record.client_code)?.telephone)}catch(x){}show('Envoyer le contrat pour signature',`<p>Le client consulte le PDF recto verso, signe, puis télécharge sa copie. Lien valable 48 heures.</p><input readonly value="${esc(url)}" id="invite-link"><button id="copy-invite" class="secondary">Copier le lien</button>${phone?`<a class="button whatsapp" href="https://wa.me/${phone}?text=${encodeURIComponent('Bonjour, merci de consulter et signer votre contrat de location : '+url)}" target="_blank" rel="noopener">Envoyer par WhatsApp</a>`:'<p>Complétez le téléphone sur la fiche client pour utiliser WhatsApp.</p>'}<p class="finance-hint">La signature revient au relais, puis sur le PC à sa prochaine synchronisation.</p>`);document.getElementById('copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Lien copié.')}catch(x){document.getElementById('invite-link').select();toast('Le lien est sélectionné : copiez-le.')}}}catch(x){if(popup)popup.close();toast(x.message)}}
async function act(action,id){try{switch(action){case'calendar-prev':case'calendar-next':{const [y,m]=calendarMonth.split('-').map(Number);const d=new Date(y,m-1+(action==='calendar-next'?1:-1),1);calendarMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');render();break}case'enable-maintenance-notifications':{if(!('Notification'in window)||!('serviceWorker'in navigator))throw Error('Notifications non disponibles sur ce navigateur.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Autorisez les notifications dans les paramètres du téléphone et du navigateur.');await atomic(st=>st.maintenanceNotifications=true);await notifyMaintenance();toast('Notifications d’entretien activées lorsque Gestion Pro est ouvert.');break}case'client-documents':show('Documents du client',clientPDFs(id)+'<p class="finance-hint">Cette liste contient les PDF importés depuis Android. Les autres documents archivés uniquement sur le PC restent consultables sur le PC.</p>');break;case'retry-client-pdf':{const o=operations().find(o=>o.id===id);if(!o||o.kind!=='document_upload'||o.status!=='rejected'||!o.pdf)throw Error('PDF à relancer indisponible.');await enqueue('document_upload',clone(o.record),{pdf:o.pdf});clientDetail(o.record.client_code);break}case'insert-client-pdf':insertClientPDF(id);break;case'open-client-pdf':{const o=operations().find(o=>o.id===id);if(o?.pdf)previewPDF(GPDoc.bytes(o.pdf),o.record.filename);break}case'dashboard-details':dashboardDetails(id);break;case'menu':document.getElementById('drawer').showModal();break;case'settings':document.getElementById('drawer').close();settings();break;case'tab':document.getElementById('drawer').close();route(id);break;case'copy-site-link':await copyWebsiteLink();break;case'new-client':clientForm();break;case'client':clientDetail(id);break;case'edit-client':clientForm(id);break;case'client-contract':bookingForm('contract',id);break;case'client-reservation':bookingForm('reservation',id);break;case'new-contract':bookingForm('contract');break;case'new-reservation':bookingForm('reservation');break;case'reservation':bookingForm('reservation','',id);break;case'reservation-contract':{const r=data().reservations.find(x=>x.reference===id);if(r)bookingForm('contract',String(r.client).split('|')[0].trim(),id,r);break;}case'vehicle':vehicleDetail(id);break;case'counter':counterForm(id);break;case'new-maintenance':maintenanceForm(id);break;case'edit-maintenance':{let r=data().maintenance.find(m=>m.reference===id);maintenanceForm(GP.vehicleCode(r),id);break}case'contract':contractDetail(id);break;case'sign-local':localSignatureForm(id);break;case'fetch-signed':{const response=await fetch('/mobile/api/contract-document',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.config.token},body:JSON.stringify({numero:id})});const result=await response.json();if(!response.ok)throw Error(result.error);if(result.pending){toast(result.message);break}await atomic(st=>st.archives[id]=result.document);contractDetail(id);break}case'preview-contract':{const a=archiveFor(id),r=data().contracts.find(c=>c.numero===id)||a?.record;const frozen=a?.frozen||{record:r,client:client(r.client_code),vehicle:vehicle(r.vehicle_code),settings:data().settings,current_km:r.km_depart,created_at:r.created_at};const cached=state.archives[id]?.unsigned_pdf;const bytes=!navigator.onLine&&cached?GPDoc.bytes(cached):await GPDoc.pdf(frozen,'');await atomic(st=>{if(!st.archives[id])st.archives[id]={record:r,frozen};st.archives[id].unsigned_pdf=GPDoc.toBase64(bytes)});previewPDF(bytes,id+' — avant signature');break}case'preview-signed':{const a=archiveFor(id);if(!a?.pdf)throw Error('Copie signée non disponible. Synchronisez le téléphone.');previewPDF(GPDoc.bytes(a.pdf),id+' — signé');break}case'pdf':{let a=archiveFor(id);if(!a?.pdf)throw Error('PDF signé absent.');GPDoc.download(GPDoc.bytes(a.pdf),'Contrat_'+id+'.pdf');break}case'whatsapp-pdf':{await whatsappContract(id);break}case'invite':await invite(id);break;case'invite-whatsapp':await invite(id,true);break;case'op-recover':{const o=operations().find(o=>o.id===id);if(!o)break;const r=o.record;toast(o.message||'Reprenez la saisie avec les données à jour.');if(o.kind.startsWith('client'))clientForm('',r);else if(o.kind==='vehicle_update')counterForm(r.code);else if(o.kind.startsWith('maintenance'))maintenanceForm(GP.vehicleCode(r),'',r);else if(o.kind.startsWith('reservation'))bookingForm('reservation',String(r.client).split('|')[0].trim(),'',r);else bookingForm('contract',r.client_code,'',{...r,start_date:r.date_depart,start_time:r.heure_depart,end_date:r.date_retour,end_time:r.heure_retour,daily_price:r.prix,deposit:r.reglement});break}case'clear-signature':pad?.clear();break;case'sync':await sync();break;case'all-finance':month='';render();break;case'install':if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('Dans Chrome : menu ⋮ → Installer l’application.');break;case'backup':GPDoc.download(new TextEncoder().encode(JSON.stringify({format:'gestionpro-mobile-v1',state:{...state,config:{token:''}},at:new Date().toISOString()})),'GestionPro_sauvegarde_'+GP.isoToday()+'.json','application/json');break;case'restore':document.getElementById('restore-file').click();break}}catch(x){toast(x.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();act(b.dataset.action,b.dataset.id)}});
document.getElementById('close-dialog').onclick=()=>dialog.close();document.getElementById('settings').onclick=settings;document.getElementById('menu-toggle').onclick=()=>document.getElementById('drawer').showModal();document.getElementById('close-menu').onclick=()=>document.getElementById('drawer').close();
main.addEventListener('input',e=>{if(e.target.id==='search'){let position=e.target.selectionStart;search=e.target.value;render();let input=document.getElementById('search');input.focus();input.setSelectionRange(position,position)}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('online',()=>{render();sync(false)});window.addEventListener('offline',render);document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync(false)});
(async()=>{try{state=await GP.get('state')||{data:blank(),queue:[],archives:{},config:{token:''},lastSync:null};await GP.set('state',state);render();if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('/mobile/sw.js',{scope:'/mobile/'});navigator.storage?.persist?.()}catch(x){toast('Installation hors connexion indisponible pour le moment.')}}await sync(false);await notifyMaintenance();setInterval(()=>sync(false),60000)}catch(x){main.innerHTML='<p class="note">Impossible d’ouvrir les données locales : '+esc(x.message)+'</p>'}})();

document.addEventListener('change',e=>{if(e.target.id==='calendar-month'){calendarMonth=e.target.value;render()}if(e.target.id==='calendar-vehicle'){calendarVehicle=e.target.value;render()}});

function previewPDF(bytes,title){const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const viewer=document.createElement('dialog');viewer.innerHTML=`<h2>${esc(title)}</h2><p>Contrat Gestion Pro recto verso.</p><a class="button" href="${url}" target="_blank" rel="noopener">Ouvrir le PDF</a><a class="button secondary" href="${url}" download="Contrat.pdf">Télécharger / imprimer</a><button type="button" class="secondary">Revenir au contrat</button><iframe title="Contrat recto verso" src="${url}" style="width:100%;height:65vh;border:0;margin-top:16px"></iframe>`;document.body.append(viewer);viewer.querySelector('button').onclick=()=>viewer.close();viewer.onclose=()=>{URL.revokeObjectURL(url);viewer.remove()};viewer.showModal()}
async function flushSignatures(){for(const [number,pending] of Object.entries(state.pendingSignatures||{})){const op=(data().operations||[]).find(o=>o.kind==='contract_create'&&o.record.numero===number);if(!op)continue;try{const response=await fetch('/mobile/api/sign-contract',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.config.token},body:JSON.stringify({op_id:op.id,signature:pending.signature,accepted:true})});const result=await response.json();if(!response.ok)throw Error(result.error||'Signature non confirmée.');await atomic(st=>{st.archives[number]={...st.archives[number],...result.document};st.data.operations=st.data.operations.map(o=>o.id===op.id?{...result.document,status:'pending'}:o);delete st.pendingSignatures[number];});}catch(x){await atomic(st=>{if(st.pendingSignatures?.[number])st.pendingSignatures[number].error=x.message});}}}
function localSignatureForm(id){const a=archiveFor(id);if(!a||a.signature)return;show('Confirmer la signature',`<h3>${esc(id)}</h3>${button('Consulter avant signature','preview-contract',id,'secondary')}<canvas id="local-signature" class="signature"></canvas><label><input type="checkbox" id="local-accept" style="width:auto"> Le client a lu et accepte le recto et le verso.</label><p id="local-status" role="status"></p><button type="button" id="local-confirm" class="teal">Valider la signature</button>`);const sig=GPDoc.signature(document.getElementById('local-signature'));document.getElementById('local-confirm').onclick=async e=>{const output=document.getElementById('local-status');try{const ink=sig.value();if(!ink||!document.getElementById('local-accept').checked)throw Error('Signature et acceptation des conditions requises.');e.target.disabled=true;await atomic(st=>{st.pendingSignatures=st.pendingSignatures||{};st.pendingSignatures[id]={signature:ink,confirmed_at:new Date().toISOString()}});await sync(false);if(!archiveFor(id)?.signature)throw Error(state.pendingSignatures[id]?.error||'Signature conservée sur le téléphone. Connectez-vous puis synchronisez pour produire le PDF signé.');contractDetail(id);toast('Signature confirmée. Le PDF signé est disponible.')}catch(x){output.textContent=x.message;e.target.disabled=false;}}}

async function whatsappContract(id){let popup=null;try{const a=archiveFor(id);if(!a?.pdf)throw Error('PDF signé absent.');const phone=GPDoc.phone(client(a.record.client_code)?.telephone||a.frozen?.client?.telephone);popup=window.open('about:blank','_blank');if(popup)popup.opener=null;await sync(false);const response=await fetch('/mobile/api/share-contract',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.config.token},body:JSON.stringify({numero:id})});const result=await response.json();if(!response.ok)throw Error(result.error);const url=location.origin+'/mobile/signature/'+result.token;const whatsappURL='https://wa.me/'+phone+'?text='+encodeURIComponent('Bonjour, voici votre contrat de location signé '+id+' (PDF recto verso) : '+url);if(popup){popup.location.href=whatsappURL;toast('Contrat signé prêt dans WhatsApp. Validez l’envoi au client.');return}show('Envoyer le contrat signé',`<p>WhatsApp s’ouvrira sur le numéro enregistré du client : ${esc(phone)}. Le message contient un lien permettant de consulter et télécharger son PDF signé, valable 48 heures.</p><a class="button whatsapp" target="_blank" rel="noopener" href="https://wa.me/${phone}?text=${encodeURIComponent('Bonjour, voici votre contrat de location signé '+id+' (PDF recto verso) : '+url)}">Envoyer au client par WhatsApp</a>${button('Télécharger le PDF pour le joindre','pdf',id,'secondary')}`)}catch(x){if(popup)popup.close();throw x}}
